import React, { useState } from 'react';

export default function BlocoEtapaVisual({ etapaId = 1 }) {
  const [tipo, setTipo] = useState('mensagem');
  const [mensagem, setMensagem] = useState('');
  const [numero, setNumero] = useState('');
  const [destino, setDestino] = useState('');

  return (
    <div className="border rounded p-4 bg-white shadow mb-4 max-w-2xl mx-auto">
      <h2 className="font-bold text-lg mb-2">Etapa #{etapaId}</h2>

      <label className="block text-sm font-medium mb-1">Mensagem para o cliente:</label>
      <textarea
        value={mensagem}
        onChange={(e) => setMensagem(e.target.value)}
        placeholder="Digite a mensagem dessa etapa..."
        rows={3}
        className="w-full border rounded p-2 mb-4"
      />

      <label className="block text-sm font-medium mb-1">Ação ao avançar:</label>
      <select
        value={tipo}
        onChange={(e) => setTipo(e.target.value)}
        className="w-full border rounded p-2 mb-4"
      >
        <option value="mensagem">➡️ Enviar nova mensagem</option>
        <option value="etapa">🔁 Ir para outra etapa</option>
        <option value="redirecionar">☎️ Redirecionar para número</option>
      </select>

      {tipo === 'mensagem' && (
        <div className="bg-blue-50 border border-blue-200 p-3 rounded text-sm text-blue-800">
          Após essa etapa, o bot enviará uma nova mensagem configurada na próxima etapa.
        </div>
      )}

      {tipo === 'etapa' && (
        <div>
          <label className="block text-sm font-medium mb-1">Número da etapa destino:</label>
          <input
            type="text"
            value={destino}
            onChange={(e) => setDestino(e.target.value)}
            placeholder="Ex: 2"
            className="w-full border rounded p-2"
          />
        </div>
      )}

      {tipo === 'redirecionar' && (
        <div>
          <label className="block text-sm font-medium mb-1">Número de WhatsApp para redirecionar:</label>
          <input
            type="text"
            value={numero}
            onChange={(e) => setNumero(e.target.value)}
            placeholder="Ex: 5511999998888"
            className="w-full border rounded p-2"
          />
        </div>
      )}
    </div>
  );
}
